# Code generated by Claude
"""
Re-profile of ONE full check with the sped-up code (src/full_check.py), next to the old numbers of docs/reports/20261022_0344_stance_check_profile.md. Timing and counting only.

    MUJOCO_GL=egl python experiments/full_check_profile.py [--out data/logs]

Runs: A cold (the stance in TASK_CFG; first call: builds the renderers, the arm collision checkers), A warm (the same, answer memory off), A under cProfile, B (the first quick-search candidate at
heading -90 degrees that fails early, as in the old profile). Prints the time per part, the counts (IK batches, starts and iterations, neck solves and cost evaluations, renders) and the top
functions by cumulative time; writes data/logs/full_check_profile_<time>.json and .prof. One sim and render job: run it alone.
"""

import argparse
import cProfile
import io
import json
import math
import pstats
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import src.full_check as FCM  # noqa: E402
import src.neck_framing as NF  # noqa: E402
import src.stance_checks as SC  # noqa: E402
from src.full_check import FullCheck, task_points  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

STAT = {}


def _rec(label, dt, **extra):
    s = STAT.setdefault(label, {"calls": 0, "seconds": 0.0})
    s["calls"] += 1
    s["seconds"] += dt
    for k, v in extra.items():
        s[k] = s.get(k, 0) + v


class Instr:
    def __init__(self):
        self.saved = []

    def wrap(self, obj, name, label, extra=None):
        orig = getattr(obj, name)

        def timed(*a, **k):
            t0 = time.perf_counter()
            r = orig(*a, **k)
            _rec(label, time.perf_counter() - t0, **(extra(a, k, r) if extra else {}))
            return r
        self.saved.append((obj, name, orig, name in getattr(obj, "__dict__", {})))
        setattr(obj, name, timed)

    def off(self):
        for obj, name, orig, had in reversed(self.saved):
            setattr(obj, name, orig) if had else delattr(obj, name)
        self.saved = []


def instrument(ins, fc):
    ins.wrap(SC, "frame_points", "neck solves (frame_points)")
    ins.wrap(SC, "best_margin", "framing slack searches (best_margin)")
    ins.wrap(NF, "_evaluate", "neck cost evaluations")
    ins.wrap(mujoco.Renderer, "render", "renders")
    ins.wrap(mujoco, "mj_geomDistance", "geom distance calls")
    ins.wrap(FCM, "solve_ik", "IK batches (solve_ik)", lambda a, k, r: {"starts": int(len(a[1])), "iterations": int(np.sum(r[2])), "converged": int(np.sum(r[1]))})
    ins.wrap(FCM.PathClearance, "arm_distances", "arm vs objects distance sets (candidates)", lambda a, k, r: {"candidates": int(len(np.atleast_2d(a[2])))})
    ins.wrap(FCM.ArmCollisionChecker, "__init__", "arm collision checker builds")
    ins.wrap(FCM.ArmCollisionChecker, "check", "arm collision checker queries")


def snapshot():
    out = {k: {kk: (round(vv, 3) if isinstance(vv, float) else vv) for kk, vv in v.items()} for k, v in STAT.items()}
    STAT.clear()
    return out


def main(args):
    t0 = time.perf_counter()
    fc = FullCheck()
    print(f"setup (the check's simulation, once per run): {time.perf_counter() - t0:.1f} s", flush=True)
    pts = task_points(fc.model, fc.scene_data)
    A = (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1], math.radians(-90.0), TASK_CFG["pedestal_q"])
    B = (0.855, 0.925, math.radians(-90.0), 0.12)
    out = {"setup_seconds": round(time.perf_counter() - t0, 1), "old": {"A cold": 284.7, "A warm": 252.4, "B": 0.54, "report": "docs/reports/20261022_0344_stance_check_profile.md"}}
    ins = Instr()
    for label in ("A cold", "A warm"):
        instrument(ins, fc)
        STAT.clear()
        t0 = time.perf_counter()
        r = fc.check(A, pts, use_cache=False)
        total = time.perf_counter() - t0
        out[label] = {"ok": r["ok"], "reason": r["reason"], "total_seconds": round(total, 2), "parts": r["seconds"], "stats": r.get("stats"), "counters": snapshot(), "ik": r["ik"]}
        ins.off()
        print(f"{label}: ok {r['ok']}, total {total:.1f} s, parts {r['seconds']}", flush=True)
    prof = cProfile.Profile()
    prof.enable()
    t0 = time.perf_counter()
    rp = fc.check(A, pts, use_cache=False)
    prof.disable()
    out["A profiled"] = {"ok": rp["ok"], "total_seconds": round(time.perf_counter() - t0, 2), "note": "with the profiler's overhead"}
    stamp = time.strftime("%Y%m%d_%H%M%S")
    prof.dump_stats(str(Path(args.out) / f"full_check_profile_{stamp}.prof"))
    sio = io.StringIO()
    pstats.Stats(prof, stream=sio).sort_stats("cumulative").print_stats(25)
    out["cprofile_top25_cumulative"] = sio.getvalue()
    instrument(ins, fc)
    STAT.clear()
    t0 = time.perf_counter()
    rb = fc.check(B, pts, use_cache=False)
    out["B"] = {"ok": rb["ok"], "failed": rb["failed"], "reason": rb["reason"], "total_seconds": round(time.perf_counter() - t0, 3), "counters": snapshot()}
    ins.off()
    print(f"B: ok {rb['ok']}, {rb['failed']}, {out['B']['total_seconds']} s", flush=True)
    p = Path(args.out) / f"full_check_profile_{stamp}.json"
    p.write_text(json.dumps(out, indent=1, default=str))
    print(f"written {p}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "logs"))
    main(ap.parse_args())
